package com.ajay.amusezone.config;
import com.ajay.amusezone.entity.*; import com.ajay.amusezone.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*;
@Configuration public class DataInitializer { @Bean CommandLineRunner seed(RideRepository rides,WaterRideRepository water,EntryTicketRepository tickets,OfferRepository offers){return args->{if(rides.count()==0){rides.save(new Ride("Roller Coaster","High-speed family coaster","Thrill",250,12));rides.save(new Ride("Ferris Wheel","Scenic giant wheel","Family",150,5));} if(water.count()==0){WaterRide w=new WaterRide();w.setName("Wave Pool");w.setDescription("Fun wave pool");w.setPrice(300);w.setMinAge(8);water.save(w);} if(tickets.count()==0){tickets.save(new EntryTicket("Adult",500));tickets.save(new EntryTicket("Child",300));} if(offers.count()==0)offers.save(new Offer("WELCOME10","10% welcome discount",10));};}}
